// Picking which caption track to save, from the InnerTube player response.

export interface CaptionTrack {
  baseUrl: string;
  languageCode: string;
  /** `asr` for auto-generated captions; absent for captions someone wrote. */
  kind?: string;
  name?: { simpleText?: string; runs?: { text: string }[] };
  vssId?: string;
}

export function isAutoGenerated(track: CaptionTrack): boolean {
  return track.kind === "asr";
}

function baseLanguage(code: string): string {
  return code.toLowerCase().split("-")[0]!;
}

/**
 * The track to save:
 * 1. captions someone wrote in the video's spoken language (the auto-generated track's language),
 * 2. the auto-generated track,
 * 3. the track YouTube itself would show first (`defaultCaptionTrackIndex`) if someone wrote it,
 * 4. any written track, English first.
 */
export function chooseCaptionTrack(
  tracks: CaptionTrack[],
  defaultTrackIndex?: number,
): CaptionTrack | null {
  const usable = tracks.filter((track) => track.baseUrl && track.languageCode);
  if (usable.length === 0) return null;

  const written = usable.filter((track) => !isAutoGenerated(track));
  const auto = usable.find(isAutoGenerated);

  if (auto) {
    const spoken = baseLanguage(auto.languageCode);
    const exact = written.find((track) => track.languageCode === auto.languageCode);
    const sameLanguage = written.find((track) => baseLanguage(track.languageCode) === spoken);
    return exact ?? sameLanguage ?? auto;
  }

  const preferred = defaultTrackIndex !== undefined ? tracks[defaultTrackIndex] : undefined;
  if (preferred && written.includes(preferred)) return preferred;

  return written.find((track) => baseLanguage(track.languageCode) === "en") ?? written[0] ?? null;
}

/** The timedtext address in the default XML form (`fmt=srv3` taken out). */
export function timedTextUrl(track: CaptionTrack): string {
  return track.baseUrl.replace(/&fmt=[^&]*/g, "").replace(/\?fmt=[^&]*&?/, "?");
}
